'use client';

import { useState, type SVGProps } from 'react';
import { cn } from '@/lib/utils';

/* Iconly Pro (Bold) glyphs, inlined so the block copies out with no icon
   dependency — the same convention the Tables wave uses. */
type IconProps = SVGProps<SVGSVGElement>;

function IconArrowUpRight(props: IconProps) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" {...props}>
      <g transform="rotate(-45 12 12)">
        <path
          transform="translate(3, 6)"
          d="M7.83655568,6.36070466 L7.8350323,6.00660914 C7.8350323,4.53497338 7.92121308,3.19331742 8.05102968,2.31870755 L8.16475558,1.77483018 C8.22802754,1.48678171 8.31120835,1.15880301 8.39793457,0.991371397 C8.71538527,0.378924178 9.33610502,0 10.0004606,0 L10.0582781,0 C10.4913637,0.0143198091 11.4011709,0.394345511 11.4011709,0.407563797 C12.8651531,1.02183092 15.6895424,2.87571834 16.9940026,4.19738844 L17.3730714,4.59418673 C17.4723361,4.70172939 17.5838596,4.82900679 17.6530951,4.92821737 C17.884365,5.23444098 18,5.61336516 18,5.99228933 C18,6.41527446 17.8701834,6.80851845 17.6247318,7.13016339 L17.2352725,7.55047018 L17.2352725,7.55047018 L17.1480103,7.6401689 C15.9643883,8.9234441 12.8738803,11.0218469 11.2571726,11.6640352 L11.0130847,11.7575787 C10.719361,11.8628603 10.3078205,11.988434 10.0582781,12 C9.74082738,12 9.43755833,11.9261979 9.14847093,11.7807968 C8.7873844,11.5770149 8.49938789,11.2553699 8.34011709,10.8764457 C8.23866377,10.6142831 8.07939298,9.82669359 8.07939298,9.81237378 C7.93338076,9.01825987 7.84871691,7.76518207 7.83655568,6.36070466 Z M1.77635684e-15,5.99955939 C1.77635684e-15,5.1612998 0.673082751,4.48165963 1.50325451,4.48165963 L5.20248239,4.80881219 C5.85374723,4.80881219 6.38174083,5.3419497 6.38174083,5.99955939 C6.38174083,6.65827061 5.85374723,7.19030659 5.20248239,7.19030659 L1.50325451,7.51745915 C0.673082751,7.51745915 1.77635684e-15,6.83781898 1.77635684e-15,5.99955939 Z"
        />
      </g>
    </svg>
  );
}

const KEYFRAMES = `
@keyframes su-release-in { from { opacity: 0; transform: translateX(-6px) } to { opacity: 1; transform: none } }
`;

export type ReleaseFeedFooterVariant = 'Feed' | 'Compact';
export type ReleaseKind = 'model' | 'api' | 'platform';

export interface FooterRelease {
  version: string;
  date: string;
  title: string;
  kind: ReleaseKind;
}

export interface ReleaseFeedFooterProps {
  brand: string;
  releases: FooterRelease[];
  changelogHref?: string;
  groups?: { title: string; links: { label: string; href: string }[] }[];
  copyright?: string;
  variant?: ReleaseFeedFooterVariant;
  className?: string;
}

const KIND_TONE: Record<ReleaseKind, string> = {
  model: 'bg-[#f9452d]/12 text-[#b32a18] dark:bg-[#E1F435]/12 dark:text-[#E1F435]',
  api: 'bg-sky-500/12 text-sky-800 dark:text-sky-300',
  platform: 'bg-black/[0.05] text-neutral-600 dark:bg-white/[0.08] dark:text-neutral-300',
};

export function ReleaseFeedFooter({
  brand,
  releases,
  changelogHref = '#',
  groups = [],
  copyright,
  variant = 'Feed',
  className,
}: ReleaseFeedFooterProps) {
  const [active, setActive] = useState<string | null>(releases[0]?.version ?? null);
  const shown = variant === 'Compact' ? releases.slice(0, 3) : releases;

  return (
    <footer
      className={cn(
        'w-full border-t border-black/[0.08] bg-white text-neutral-900 dark:border-white/[0.09] dark:bg-[#0A0A0B] dark:text-neutral-100',
        className,
      )}
    >
      <style dangerouslySetInnerHTML={{ __html: KEYFRAMES }} />

      <div className="mx-auto w-full max-w-[1180px] px-6 py-12">
        <div className="grid gap-10 lg:grid-cols-[minmax(0,1.1fr)_minmax(0,1fr)]">
          <div>
            <div className="flex items-baseline justify-between gap-4">
              <span className="font-mono text-[10.5px] font-medium uppercase tracking-[0.09em] text-neutral-500 dark:text-neutral-400">
                Recent releases
              </span>
              <a
                href={changelogHref}
                className="group inline-flex items-center gap-1 text-[12.5px] font-medium text-neutral-600 transition-colors duration-150 hover:text-neutral-950 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-neutral-400 dark:text-neutral-400 dark:hover:text-neutral-50"
              >
                Full changelog
                <IconArrowUpRight className="size-3.5 transition-transform duration-[180ms] ease-[cubic-bezier(0.23,1,0.32,1)] group-hover:-translate-y-0.5 group-hover:translate-x-0.5 motion-reduce:transition-none" />
              </a>
            </div>

            <ol className="relative mt-5 pl-[86px]">
              <span
                aria-hidden
                className="absolute bottom-2 left-[78px] top-2 w-px bg-black/[0.09] dark:bg-white/[0.1]"
              />
              {shown.map((release, index) => {
                const open = active === release.version;
                return (
                  <li
                    key={release.version}
                    className="relative animate-[su-release-in_260ms_cubic-bezier(0.23,1,0.32,1)_backwards] py-2.5 motion-reduce:animate-none"
                    style={{ animationDelay: `${index * 40}ms` }}
                  >
                    <span className="absolute -left-[86px] top-[13px] w-[70px] text-right font-mono text-[10.5px] tabular-nums text-neutral-500 dark:text-neutral-400">
                      {release.date}
                    </span>
                    <span
                      aria-hidden
                      className={cn(
                        'absolute -left-[12px] top-[15px] size-[7px] rounded-full ring-4 transition-colors duration-200',
                        open
                          ? 'bg-neutral-900 ring-white dark:bg-neutral-100 dark:ring-[#0A0A0B]'
                          : 'bg-black/[0.16] ring-white dark:bg-white/[0.22] dark:ring-[#0A0A0B]',
                      )}
                    />
                    <a
                      href={changelogHref}
                      onMouseEnter={() => setActive(release.version)}
                      onFocus={() => setActive(release.version)}
                      className="block rounded-lg px-2 py-1 transition-colors duration-150 hover:bg-black/[0.03] focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-neutral-400 dark:hover:bg-white/[0.04]"
                    >
                      <span className="flex flex-wrap items-center gap-2">
                        <span className="font-mono text-[11.5px] tabular-nums text-neutral-500 dark:text-neutral-400">
                          v{release.version}
                        </span>
                        <span
                          className={cn(
                            'rounded-full px-1.5 py-px font-mono text-[9.5px] uppercase tracking-[0.06em]',
                            KIND_TONE[release.kind],
                          )}
                        >
                          {release.kind}
                        </span>
                      </span>
                      <span className="mt-0.5 block text-pretty text-[13.5px] leading-[1.45] text-neutral-800 dark:text-neutral-200">
                        {release.title}
                      </span>
                    </a>
                  </li>
                );
              })}
            </ol>
          </div>

          <div className="self-start">
            <p className="text-[17px] font-semibold tracking-[-0.3px]">{brand}</p>
            {groups.length > 0 && (
              <nav aria-label="Footer" className="mt-6 grid gap-8 sm:grid-cols-2">
                {groups.map((group) => (
                  <div key={group.title}>
                    <p className="text-[13px] font-medium text-neutral-900 dark:text-neutral-50">
                      {group.title}
                    </p>
                    <ul className="mt-4 space-y-2.5">
                      {group.links.map((link) => (
                        <li key={link.label}>
                          <a
                            href={link.href}
                            className="text-[13.5px] text-neutral-600 transition-colors duration-150 hover:text-neutral-950 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-neutral-400 dark:text-neutral-400 dark:hover:text-neutral-50"
                          >
                            {link.label}
                          </a>
                        </li>
                      ))}
                    </ul>
                  </div>
                ))}
              </nav>
            )}
          </div>
        </div>

        <p className="mt-10 border-t border-black/[0.07] pt-6 text-[12px] tabular-nums text-neutral-500 dark:border-white/[0.08]">
          {copyright ?? `© ${brand}. All rights reserved.`}
        </p>
      </div>
    </footer>
  );
}

export default ReleaseFeedFooter;
